@lru_cache(maxsize=128)
def icon(name: str, color: str = "#EDF2F8", size: int = 18) -> QIcon:
    svg = _SVG.get(name)
    if svg is None:
        return QIcon()
    data = QByteArray(svg.format(color=color).encode("utf-8"))
    renderer = QSvgRenderer(data)
    scale = 2
    pixmap = QPixmap(size * scale, size * scale)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing)
    renderer.render(painter)
    painter.end()
    pixmap.setDevicePixelRatio(scale)
    return QIcon(pixmap)


def pixmap(name: str, color: str, size: int = 18) -> QPixmap:
    return icon(name, color, size).pixmap(QSize(size, size))
